"""Run actual legacy PNG/image palette functions against generated byte fixtures."""
from pathlib import Path
import hashlib,json,struct,subprocess,zlib
ROOT=Path(__file__).resolve().parents[2]
SOURCE=ROOT/"legacy/src-tauri/src/platform_palette.rs"
OWNED=ROOT/"native/build/palette-image-oracle-owned"
OUTPUT=ROOT/"native/tests/fixtures/palette_image_legacy.h"
(OWNED/"src").mkdir(parents=True,exist_ok=True)
source=SOURCE.read_text(encoding="utf-8")
legacy=source[source.index("fn ordered_image_colors("):source.index("fn read_imported_palette_bytes(")]
driver=r"""
use std::{collections::HashSet,io::Cursor,path::Path};use serde::Serialize;
#[derive(Serialize)]struct PaletteColor{r:u8,g:u8,b:u8,a:u8}
const MAX_IMPORTED_PALETTE_COLORS:usize=65536;const MAX_IMPORTED_IMAGE_PIXELS:u64=16777216;
fn main(){let args:Vec<_>=std::env::args().collect();let b=std::fs::read(&args[1]).unwrap();let cases:Vec<(String,Vec<u8>)>=serde_json::from_slice(&b).unwrap();let out:Vec<_>=cases.iter().map(|(extension,bytes)|{let result=if extension=="png"{png_imported_colors(bytes)}else{image_imported_colors(bytes,Path::new("oracle"))};result.ok()}).collect();println!("{}",serde_json::to_string(&out).unwrap());}
"""
(OWNED/"Cargo.toml").write_text('[package]\nname="palette-image-legacy-oracle"\nversion="0.1.0"\nedition="2021"\n[workspace]\n[dependencies]\nserde={version="=1.0.229",features=["derive"]}\nserde_json="=1.0.151"\npng={version="=0.18.1",features=["zlib-rs"]}\nimage={version="=0.25.10",default-features=false,features=["png","jpeg","gif","bmp","webp","ico"]}\n',encoding="utf-8")
(OWNED/"src/main.rs").write_text(driver+legacy,encoding="utf-8")
cases=[]
def add(ext,b):cases.append((ext,b))
def chunk(kind,b):return struct.pack('>I',len(b))+kind+b+struct.pack('>I',zlib.crc32(kind+b))
def png(w,h,depth,kind,rows,table=b'',alpha=b'',interlace=0):
 b=b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',w,h,depth,kind,0,0,interlace))
 if table:b+=chunk(b'PLTE',table)
 if alpha:b+=chunk(b'tRNS',alpha)
 return b+chunk(b'IDAT',zlib.compress(rows))+chunk(b'IEND',b'')
for kind in [0,2,3,4,6]:
 for depth in [1,2,4,8,16]:
  channels={0:1,2:3,3:1,4:2,6:4}[kind];stride=(5*depth*channels+7)//8
  rows=b''.join(b'\0'+bytes((i*37+y*17)%256 for i in range(stride))for y in range(3))
  table=bytes(v for i in range(256)for v in [i,255-i,i//2])if kind==3 else b''
  alpha=bytes(range(256))if kind==3 else b''
  b=png(5,3,depth,kind,rows,table,alpha)
  add('png',b);add('jpg',b)
# RGB tRNS: preserve transparent RGB as legacy PNG alpha expansion.
for rgb in [(17,34,51),(0,0,0),(255,128,1)]:
 rows=b'\0'+bytes(rgb)+bytes([68,85,102])+bytes(rgb)
 add('png',png(3,1,8,2,rows,alpha=b''.join(struct.pack('>H',v)for v in rgb)))
# All PNG row filters with independent original rows.
original=[bytes((i*17+y*23)%256 for i in range(28))for y in range(5)]
for filterType in range(5):
 rows=b'';previous=bytes(28)
 for row in original:
  encoded=[]
  for i,v in enumerate(row):
   a=row[i-4]if i>=4 else 0;b=previous[i];c=previous[i-4]if i>=4 else 0
   p=a+b-c;pa,pb,pc=abs(p-a),abs(p-b),abs(p-c)
   predictor=[0,a,b,(a+b)//2,a if pa<=pb and pa<=pc else b if pb<=pc else c][filterType]
   encoded.append((v-predictor)%256)
  rows+=bytes([filterType])+bytes(encoded);previous=row
 add('png',png(7,5,8,6,rows))
# Tiny GIF clear codes keep LZW width fixed, including local palette and offsets.
def gif(w,h,left,top,pw,ph,indices,transparent=None,local=False,interlace=False):
 table=bytes([17,34,51,68,85,102]);b=b'GIF89a'+struct.pack('<HHBBB',w,h,0x80,0,0)+table
 if transparent is not None:b+=bytes([0x21,0xf9,4,1,0,0,transparent,0])
 b+=b','+struct.pack('<HHHHB',left,top,pw,ph,(0x80 if local else 0)|(0x40 if interlace else 0))
 if local:b+=bytes([119,136,153,170,187,204])
 codes=[]
 for i in indices:codes.extend([4,i])
 codes.append(5);bits=0;used=0;data=[]
 for c in codes:
  bits|=c<<used;used+=3
  while used>=8:data.append(bits&255);bits>>=8;used-=8
 if used:data.append(bits)
 b+=bytes([2,len(data)])+bytes(data)+b'\0;';return b
for local in [False,True]:
 for alpha in [None,0,1]:
  for left,top,pw,ph in [(0,0,3,2),(1,1,2,1),(2,1,3,2),(4,0,1,1)]:
   add('gif',gif(3,2,left,top,pw,ph,[i%2 for i in range(pw*ph)],alpha,local))
for b in [gif(3,2,0,0,3,2,[0,1,0,1,0,1]),png(2,1,8,6,b'\0'+bytes([17,34,51,0,68,85,102,255]))]:
 for n in [0,1,8,len(b)//2,len(b)-1]:add('gif'if b[:3]==b'GIF'else'png',b[:n])
tail=png(2,1,8,6,b'\0'+bytes([17,34,51,0,68,85,102,255]))
for cut in range(13):add('png',tail[:len(tail)-cut])
for position in [29,len(tail)-1,len(tail)-5,len(tail)-13]:
 bad=bytearray(tail);bad[position]^=1;add('png',bytes(bad))
for kind in [b'tEXt',b'abCD']:
 extra=chunk(kind,b'ignored');bad=bytearray(extra);bad[-1]^=1
 add('png',tail[:-12]+extra+tail[-12:]);add('png',tail[:-12]+bytes(bad)+tail[-12:])
(OWNED/"input.json").write_text(json.dumps([(e,list(b))for e,b in cases]),encoding='utf-8')
subprocess.run(['cargo','--config',str(ROOT/'legacy/.cargo/config.toml'),'build','--offline','--release','--manifest-path',str(OWNED/'Cargo.toml')],check=True)
results=json.loads(subprocess.run([str(OWNED/'target/release/palette-image-legacy-oracle.exe'),str(OWNED/'input.json')],check=True,capture_output=True).stdout)
rows=[]
for (ext,b),colors in zip(cases,results):
 packed=[]if colors is None else[c['r']|(c['g']<<8)|(c['b']<<16)|(c['a']<<24)for c in colors]
 rows.append('{"'+ext+'",{'+','.join(str(v)for v in b)+'},'+('false'if colors is None else'true')+',{'+','.join(hex(v)+'u'for v in packed)+'}}')
OUTPUT.write_text('#pragma once\n// Generated by make-palette-image-fixtures.py from actual legacy image/png functions.\n// Source SHA256: '+hashlib.sha256(SOURCE.read_bytes()).hexdigest()+'\nstruct LegacyImagePaletteFixture{const char* extension;std::vector<std::uint8_t> bytes;bool accepted;std::vector<moon::Pixel> colors;};\ninline const std::vector<LegacyImagePaletteFixture> legacyImagePaletteFixtures={\n'+',\n'.join(rows)+'\n};\n',encoding='utf-8',newline='\n')
print(f'Generated {len(cases)} actual legacy PNG/GIF cases')
